package probe
import "errors"
func Calc(x int)(int,error){if x<0{return 0,errors.New("negative")};return x+1,nil}

package probe
import "errors"
func core(x int)int{return x+1}
func Checked(x int)(int,error){if x<0{return 0,errors.New("negative")};return core(x),nil}
func Raw(x int)int{return core(x)}

