type Box struct {state int}
func(b *Box) A(x int)int{old:=b.state;b.state=x;return old}
func(b *Box) B(x int)int{old:=b.state;b.state=x;return old}

package probe
func core(x int,mode bool)int{if mode{return x+1};return x*2}
func Configured(x int,mode bool)int{return core(x,mode)}
func Default(x int)int{return core(x,false)}

